// And groups predicates with the AND operator between them.
func And(predicates ...predicate.TransferShare) predicate.TransferShare {
	return predicate.TransferShare(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.TransferShare) predicate.TransferShare {
	return predicate.TransferShare(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.TransferShare) predicate.TransferShare {
	return predicate.TransferShare(sql.NotPredicates(p))
}
